                        # has_zero=True: zero out factor exponents so cache states collapse
                        res += dp(pos + 1, csum + d, 0, 0, 0, 0, 1, new_tight, True)
                    else:
                        f = fact[d]
                        if has_zero:
                            res += dp(pos + 1, csum + d, 0, 0, 0, 0, 1, new_tight, True)
                        else:
