                                pos + 1,
                                csum + d,
                                a2 + f[0],
                                a3 + f[1],
                                a5 + f[2],
                                a7 + f[3],
                                0,
                                new_tight,
                                True,
                            )
                return res

            ans = dp(0, 0, 0, 0, 0, 0, 0, True, False)
            dp.cache_clear()
            return ans

